<?php
require __DIR__.'/../app/bootstrap.php';admin_required();$pdo=db();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);if(($_POST['action']??'')==='avatar'){$pdo->prepare('UPDATE users SET avatar_path=NULL WHERE id=?')->execute([$id]);$notice='Аватар прибрано.';}elseif($id && $id!==current_user_id()){$pdo->prepare("UPDATE users SET blocked_at=CASE WHEN blocked_at IS NULL THEN CURRENT_TIMESTAMP ELSE NULL END WHERE id=?")->execute([$id]);$notice='Статус користувача змінено.';}}
$users=$pdo->query('SELECT u.*,(SELECT COUNT(*) FROM topics t WHERE t.user_id=u.id) topics,(SELECT COUNT(*) FROM posts p WHERE p.user_id=u.id) posts FROM users u ORDER BY u.created_at DESC')->fetchAll();forum_header('Користувачі — Admin');?><section class="page-title"><a href="/admin/">← Адмінка</a><h1>Користувачі</h1></section><?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif;?><div class="admin-table"><?php foreach($users as $u):?><div class="admin-row"><div><strong><?=e($u['display_name'])?></strong><span><?=e($u['email'])?> · <?=e($u['role'])?> · <?=e((string)$u['topics'])?> тем · <?=e((string)$u['posts'])?> відповідей</span><small><?=$u['blocked_at']?'заблокований':'активний'?></small></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button name="action" value="avatar" class="btn">Прибрати аватар</button></form><?php if((int)$u['id']!==current_user_id()):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)$u['id'])?>"><button class="btn"><?=$u['blocked_at']?'Розблокувати':'Заблокувати'?></button></form><?php endif;?></div><?php endforeach;?></div><?php forum_footer(); ?>
